     * Withdraw an owed action. This is also how an application closes a custom action once the user has finished its step. Emits user.required_action_cleared. 404 when it is not open.
     *
     * `DELETE /v1/users/{id}/required_actions/{rid}` (scope `users:write`)
     *
     * @param string $id the `id` path segment
     * @param string $rid the `rid` path segment
     * @param string|null $idempotencyKey sent as `Idempotency-Key`; a retry with the same key replays the first response
     * @return array{object:mixed, id:string, deleted:mixed}
     */
    public function deleteRequiredAction(string $id, string $rid, ?string $idempotencyKey = null): array
    {
        $r = $this->http->request('DELETE', '/v1/users/' . rawurlencode($id) . '/required_actions/' . rawurlencode($rid), idempotencyKey: $idempotencyKey);

        return is_array($r) ? $r : [];
    }

    /**
     * Remove a registered certificate mapping.
     *
     * `DELETE /v1/users/{id}/smartcard_mappings/{mappingId}` (scope `users:write`)
     *
     * @param string $id the `id` path segment
     * @param string $mappingid the `mappingId` path segment
     * @return array{object:mixed, id:string, deleted:mixed}
     */
    public function deleteSmartcardMapping(string $id, string $mappingid): array
    {
        $r = $this->http->request('DELETE', '/v1/users/' . rawurlencode($id) . '/smartcard_mappings/' . rawurlencode($mappingid));

        return is_array($r) ? $r : [];
    }

    /**
     * The user's active temporary access passes (never the codes).
     *
     * `GET /v1/users/{id}/temporary_access` (scope `users:read`)
     *
     * @param string $id the `id` path segment
     * @param array{limit?:int, starting_after?:string} $query
     * @return array{object?:mixed, data?:list<array{object:mixed, id:string, user_id:string, expires_at:int, uses_left:int, require_enrolment:bool, bound_ip:string|null, issued_by:string|null, reason:string|null, last_used_at:int|null, created_at:int}>, has_more?:bool, next_cursor?:string|null}
     */
    public function listTemporaryAccess(string $id, array $query = []): array
    {
        $r = $this->http->request('GET', '/v1/users/' . rawurlencode($id) . '/temporary_access', query: $query);

        return is_array($r) ? $r : [];
    }

    /**
     * Every item of `listTemporaryAccess` across all pages (cursor pagination), one at a time.
     *
     * @param string $id the `id` path segment
     * @param array{limit?:int, starting_after?:string} $query
     * @return \Generator<int,mixed>
     */
    public function listTemporaryAccessAll(string $id, array $query = []): \Generator
    {
        return \Atlas\Pagination::iterate(fn (array $q): array => $this->listTemporaryAccess($id, $q), $query);
    }

    /**
     * Issue a temporary access pass: a time-limited code (60 seconds to 7 days, one use by default) that signs the user in with `strategy: "temporary_access_pass"`, counts as MFA for that sign-in, and (unless `require_enrolment` is false) makes them register a passkey or second factor. Optionally bound to an IP. The code is shown once.
     *
     * `POST /v1/users/{id}/temporary_access` (scope `users:write`)
     *
     * @param string $id the `id` path segment
     * @param array{lifetime_seconds?:int, one_time?:bool, uses?:int, require_enrolment?:bool, bound_ip?:string, reason?:string} $body
     * @param string|null $idempotencyKey sent as `Idempotency-Key`; a retry with the same key replays the first response
     * @return array{object:mixed, id:string, user_id:string, expires_at:int, uses_left:int, require_enrolment:bool, bound_ip:string|null, issued_by:string|null, reason:string|null, last_used_at:int|null, created_at:int, code:string}
     */
    public function temporaryAccess(string $id, array $body = [], ?string $idempotencyKey = null): array
    {
        $r = $this->http->request('POST', '/v1/users/' . rawurlencode($id) . '/temporary_access', body: $body, idempotencyKey: $idempotencyKey);

        return is_array($r) ? $r : [];
    }

    /**
     * Revoke a temporary access pass.
     *
     * `DELETE /v1/users/{id}/temporary_access/{pass_id}` (scope `users:write`)
     *
     * @param string $id the `id` path segment
     * @param string $passId the `pass_id` path segment
     * @return array{object?:mixed, id?:string, deleted?:mixed}
     */
    public function deleteTemporaryAccess(string $id, string $passId): array
    {
        $r = $this->http->request('DELETE', '/v1/users/' . rawurlencode($id) . '/temporary_access/' . rawurlencode($passId));

        return is_array($r) ? $r : [];
    }
}
